const fs=require('fs'),path=require('path');const root='outputs/dracula-food';
const p={id:'alune-de-padure-dracula-farm',sku:'DF-002',price:59,category:'pantry',image:'/assets/produse/dracula-food-alune-de-padure-dracula-farm.png',name:{ro:'Alune de pădure Dracula-Farm',en:'Dracula-Farm Hazelnuts',de:'Dracula-Farm Haselnüsse'},description:{ro:'O selecție cu caracter, în aceeași semnătură Dracula-Farm. Alune de pădure într-un ambalaj negru, cu detalii roșii și o prezență discretă.',en:'A selection with character, bearing the Dracula-Farm signature. Hazelnuts in black packaging, with red details and a quietly distinctive presence.',de:'Eine Auswahl mit Charakter und der Dracula-Farm Signatur. Haselnüsse in schwarzer Verpackung mit roten Details und einem dezenten, unverwechselbaren Auftritt.'},details:{ro:'Alune de pădure Dracula-Farm, prezentate în macheta de ambalaj de 500 g furnizată. Alergen: alune de pădure. Fotografia ilustrează conceptul de prezentare. Compoziția finală, cantitatea comercială, informațiile nutriționale și condițiile de păstrare vor fi confirmate înainte de vânzare. Prețul afișat este demonstrativ.',en:'Dracula-Farm hazelnuts, shown in the supplied 500 g packaging mockup. Allergen: hazelnuts. The image illustrates the presentation concept. Final composition, retail quantity, nutrition information and storage conditions will be confirmed before sales begin. The displayed price is illustrative.',de:'Dracula-Farm Haselnüsse im bereitgestellten Verpackungsentwurf für 500 g. Allergen: Haselnüsse. Das Bild zeigt das Gestaltungskonzept. Endgültige Zusammensetzung, Verkaufsmenge, Nährwertangaben und Lagerbedingungen werden vor Verkaufsbeginn bestätigt. Der angezeigte Preis ist ein Beispielpreis.'}};
const catalogFile=path.join(root,'food/catalog.json'),products=JSON.parse(fs.readFileSync(catalogFile));if(!products.some(x=>x.id===p.id))products.push(p);fs.writeFileSync(catalogFile,JSON.stringify(products,null,2)+'\n');
const changes={'collection.description':{ro:'Nuci și alune de pădure. Două selecții Dracula-Farm, prezentate cu aceeași atenție pentru detaliu.',en:'Walnuts and hazelnuts. Two Dracula-Farm selections, presented with the same attention to detail.',de:'Walnüsse und Haselnüsse. Zwei Dracula-Farm Auswahlen, präsentiert mit derselben Liebe zum Detail.'}};
const images={hero:'/assets/brand/dracula-food-logo.jpeg',collection:products[0].image,scarf:p.image};
for(const file of ['food/overrides.json','backend/dracula-content.json']){const f=path.join(root,file),d=JSON.parse(fs.readFileSync(f));Object.assign(d.ui,changes);d.images=images;if(file.startsWith('backend/'))d.products=products;fs.writeFileSync(f,JSON.stringify(d,null,2)+'\n');}
let f=path.join(root,'food/build_overrides.py'),s=fs.readFileSync(f,'utf8');for(const [key,v] of Object.entries(changes)){const line='add('+[key,v.ro,v.en,v.de].map(x=>JSON.stringify(x)).join(', ')+')';s=s.replace(new RegExp('add\\([\'\"]'+key.replaceAll('.','\\.')+'[\'\"][^\\n]*'),line);}s=s.replace("    'ui': ui, 'pages': pages,","    'images': "+JSON.stringify(images)+",\n    'ui': ui, 'pages': pages,");fs.writeFileSync(f,s);
f=path.join(root,'backend/seed_dracula.py');s=fs.readFileSync(f,'utf8').replace(/'dracula_images':\{[^}]*\}/,"'dracula_images':"+JSON.stringify(images));fs.writeFileSync(f,s);
f=path.join(root,'ops/sync-from-design.py');s=fs.readFileSync(f,'utf8').replace("repr({'hero':overlay['brand']['logo'],'collection':overlay['brand']['logo'],'scarf':overlay['brand']['logo']})","repr(overlay.get('images', {'hero':overlay['brand']['logo'],'collection':overlay['brand']['logo'],'scarf':overlay['brand']['logo']}))");fs.writeFileSync(f,s);
for(const dest of ['food/assets/produse','backend/public/assets/produse'])fs.copyFileSync('work/food-product-2.png',path.join(root,dest,path.basename(p.image)));
f=path.join(root,'inventar-imagini.csv');s=fs.readFileSync(f,'utf8');if(!s.includes(path.basename(p.image)))s+='https://chatgpt.com/s/m_6ab6921286f48191b2489c962fbe7245,produs alune de padure Dracula-Farm,backend/public'+p.image+',0da62021daed4ac46c40efdb2859ec761104b97b22e69fcbdf22923e395bd522,original nemodificat\n';fs.writeFileSync(f,s);
f=path.join(root,'food/build-manifest.json');const manifest=JSON.parse(fs.readFileSync(f));manifest.products=products.length;fs.writeFileSync(f,JSON.stringify(manifest,null,2)+'\n');
console.log('Food catalog:',products.map(p=>p.name.ro).join(', '));
